// Source content for 重拾. Edit here, then run `npm run content` to regenerate js/content.gen.js.
//
// Conventions
//   字{pīnyīn}   forces the reading of the preceding character (for polyphones the generator gets wrong)
//   ex: 'a|b|c'  example sentence pre-cut into tiles for the 连句 puzzle. Keep punctuation attached to tiles
//                so only one order is grammatical.
//   Speaker 'T' is the learner (the advisor, 老师); 'S' is the student.
//   In questions, the FIRST option is the correct one (shuffled at runtime).
//   A chunk's `zh` is its identity for saved progress — fixing a typo resets that one card.

const L = (s, zh, en) => ({ s, zh, en });
const Q = (q, ok, x1, x2, why) => ({ q, opts: [ok, x1, x2], why });
const C = (zh, en, note, ex, exEn) => ({ zh, en, note, ex, exEn });

